"""Every scenario in conformance/editor.v1.json, generated by the TypeScript editor."""

import json
import unittest
from pathlib import Path
from typing import Any

from super_editor import Editor

PATH = Path(__file__).resolve().parents[3] / "conformance" / "editor.v1.json"


class EditorConformance(unittest.TestCase):
    def test_scenarios(self) -> None:
        data = json.loads(PATH.read_text())
        steps = 0
        for entry in data["scenarios"]:
            scenario = entry["scenario"]
            clock = [""]
            editor = Editor(scenario["initial"], now=lambda c=clock: c[0], history_limit=scenario.get("historyLimit"))
            for index, step in enumerate(entry["steps"]):
                clock[0] = step["now"]
                got: dict[str, Any]
                if step["action"] == "apply":
                    got = editor.apply(step["input"])
                elif step["action"] == "undo":
                    got = editor.undo(step["input"]["actor"], step["input"]["expectedRevision"])
                else:
                    got = editor.redo(step["input"]["actor"], step["input"]["expectedRevision"])
                with self.subTest(scenario=scenario["name"], step=index):
                    self.assertEqual(got, step["expect"])
                steps += 1
            with self.subTest(scenario=scenario["name"], part="log"):
                self.assertEqual(editor.revisions, scenario["revisions"])
                self.assertEqual(editor.snapshot, scenario["final"])
        self.assertGreaterEqual(steps, 1000)


if __name__ == "__main__":
    unittest.main()
